bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec "$cid" grep -Fq 'reconcileIncremental' /opt/videobot/src/runtime/creatorPollingMain.mjs || exit 63
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,
 database:env.VIDEOBOT_DB_NAME,
 password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
try {
 const cursor=await pool.query('SELECT next_offset,last_complete_at FROM videobot_stars_refund_audit_cursor WHERE cursor_id=1');
 if(cursor.rows.length!==1)throw Error('CURSOR_NOT_COMMITTED');
 const row=cursor.rows[0],offset=Number(row.next_offset);
 if(!Number.isSafeInteger(offset)||offset<0)throw Error('CURSOR_INVALID');
 if(row.last_complete_at!==null) console.log('STARS_REFUND_OFFICIAL_AUDIT=AT_LEAST_ONE_FULL_PASS');
 else console.log('STARS_REFUND_OFFICIAL_AUDIT=PARTIAL_PAGES');
 const q=await pool.query('SELECT COUNT(*)::int AS n FROM videobot_sticker_refunds');
 if(q.rows.length!==1||q.rows[0].n<0)throw Error('REFUND_TABLE_UNAVAILABLE');
 console.log('STARS_REFUND_DURABLE_AUDIT_CURSOR=PASS');
}catch(error){console.log('STARS_REFUND_DURABLE_AUDIT_CURSOR=NOT_VERIFIED');process.exitCode=64;}
finally{await pool.end();}
NODE
echo STARS_REFUND_AUDIT_LIVE_READBACK=PASS
